<?php
 namespace QQWorld\Quote\Model; use QQWorld\Catalog\Model\Product\Type; use QQWorld\TestFramework\Helper\Bootstrap; class QuoteManagementTest extends \PHPUnit\Framework\TestCase { public function testSubmit() { $objectManager = Bootstrap::getObjectManager(); $quote = $objectManager->create(\QQWorld\Quote\Model\Quote::class); $quote->load('test01', 'reserved_order_id'); $model = $objectManager->create(\QQWorld\Quote\Api\CartManagementInterface::class); $order = $model->submit($quote); $orderItems = $order->getItems(); $this->assertCount(3, $orderItems); foreach ($orderItems as $orderItem) { if ($orderItem->getProductType() == Type::TYPE_SIMPLE) { $this->assertNotEmpty($orderItem->getParentItem(), 'Parent is not set for child product'); $this->assertNotEmpty($orderItem->getParentItemId(), 'Parent is not set for child product'); } } } } 